  'n3-541': { ja: '[社長|しゃちょう][夫人|ふじん]もパーティーに[来|きた]られた。', zh: '社長夫人也來參加了派對。' },
  'n3-542': { ja: '[彼|かれ]は[三人|さんにん][兄弟|きょうだい]の[長男|ちょうなん]だ。', zh: '他是三兄弟中的長子。' },
