  'n3-545': { ja: '[末っ子|すえっこ]なので[家族|かぞく]にかわいがられた。', zh: '因為是老么，很受家人疼愛。' },
  'n3-546': { ja: '[一人っ子|ひとりっこ]なので[兄弟|きょうだい]がうらやましかった。', zh: '因為是獨生子，很羨慕有兄弟姊妹的人。' },
  'n3-547': { ja: 'あの[双子|ふたご]は[顔|かお]がそっくりで[見分|みわ]けがつかない。', zh: '那對雙胞胎長得一模一樣，分辨不出來。' },
  'n3-548': { ja: '[公園|こうえん]で[親子|おやこ]がボール[遊|あそ]びをしている。', zh: '公園裡有親子在玩球。' },
  'n3-549': { ja: 'お[盆|ぼん]には[祖先|そせん]のお[墓参|はかまい]りに[行|い]く。', zh: '盂蘭盆節會去掃祖先的墓。' },
  'n3-550': { ja: 'この[森|もり]を[子孫|しそん]に[残|のこ]したい。', zh: '想把這片森林留給後代子孫。' },
