  'n3-1174': { ja: '[毎朝|まいあさ]、[体重計|たいじゅうけい]に[乗|の]る。', zh: '每天早上都量體重。' },
  'n3-1175': { ja: '[温度計|おんどけい]は[三|さん][十|じゅう][五|ご][度|ど]を[示|しめ]している。', zh: '溫度計顯示三十五度。' },
