  'n3-1180': { ja: '[熱|あつ]いお[茶|ちゃ]を[少|すこ]し[冷|さ]ましてから[飲|の]む。', zh: '把熱茶稍微放涼再喝。' },
  'n3-1181': { ja: '[寒|さむ]さで[池|いけ]の[水|みず]が[凍|こお]った。', zh: '天氣冷得池水結冰了。' },
  'n3-1182': { ja: 'チョコレートを[溶|と]かしてケーキを[作|つく]る。', zh: '融化巧克力來做蛋糕。' },
  'n3-1183': { ja: '[天井|てんじょう]からランプを[吊|つ]るした。', zh: '從天花板吊了一盞燈。' },
