  'n3-1199': { ja: 'トラックに[荷物|にもつ]を[積|つ]んだ。', zh: '把貨物裝上了卡車。' },
  'n3-1200': { ja: 'ボールが[坂|さか]を[転|ころ]がっていった。', zh: '球滾下了坡。' },
  'n3-1201': { ja: '[重|おも]い[石|いし]を[転|ころ]がして[運|はこ]んだ。', zh: '把重石頭滾著搬運。' },
