  'n3-1208': { ja: 'プロジェクターで[画像|がぞう]を[壁|かべ]に[映|うつ]した。', zh: '用投影機把圖片投在牆上。' },
  'n3-1209': { ja: '[公園|こうえん]の[桜|さくら]が[咲|さ]いた。', zh: '公園的櫻花開了。' },
  'n3-1210': { ja: '[水|みず]をやらなかったので[花|はな]が[枯|か]れた。', zh: '因為沒澆水，花枯萎了。' },
  'n3-1211': { ja: '[今年|ことし]はみかんがたくさん[実|みの]った。', zh: '今年橘子結實累累。' },
  'n3-1212': { ja: '[夏|なつ]になると[草|くさ]が[茂|しげ]る。', zh: '到了夏天草就長得很茂盛。' },
  'n3-1213': { ja: '[庭|にわ]に[雑草|ざっそう]が[生|は]えてきた。', zh: '院子裡長出了雜草。' },
  'n3-1214': { ja: '[今日|きょう]は[一日中|いちにちじゅう][日|ひ]が[照|て]っていた。', zh: '今天一整天都是大太陽。' },
  'n3-1215': { ja: '[夜空|よぞら]に[星|ほし]が[輝|かがや]いている。', zh: '夜空中星星閃耀著。' },
  'n3-1216': { ja: 'この[山|やま]からはきれいな[水|みず]が[湧|わ]いている。', zh: '這座山湧出乾淨的泉水。' },
  'n3-1217': { ja: '[誰|だれ]かが[手紙|てがみ]を[燃|も]やしたようだ。', zh: '好像有人把信燒掉了。' },
  'n3-1218': { ja: 'ぬれた[靴|くつ]をストーブで[乾|かわ]かした。', zh: '用暖爐把濕鞋烘乾了。' },
  'n3-1219': { ja: '[雨|あめ]の[日|ひ]は[洗濯|せんたく][物|ぶつ]が[湿|しめ]ったままだ。', zh: '下雨天衣服一直都是濕的。' },
  'n3-1220': { ja: '[夜中|やちゅう]に[犬|いぬ]が[激|はげ]しく[吠|ほ]えた。', zh: '半夜狗叫得很兇。' },
  'n3-1221': { ja: '[朝|あさ]から[鳥|とり]が[鳴|な]いている。', zh: '鳥從早上就在叫。' },
