  'n3-1227': { ja: 'タクシーは[客|きゃく]を[駅前|えきまえ]で[降|お]ろした。', zh: '計程車讓客人在車站前下車。' },
  'n3-1228': { ja: '[道|みち]に[迷|まよ]ったので[引き返|ひきかえ]した。', zh: '迷路了，所以折返回去。' },
