  'n3-1230': { ja: '[寝|ね]てしまって[一|いち][駅|えき][乗り過|のりす]ごした。', zh: '睡著了，多坐了一站。' },
  'n3-1231': { ja: '[気温|きおん]が[四|よん][十|じゅう][度|ど]を[超|こ]えた。', zh: '氣溫超過了四十度。' },
  'n3-1232': { ja: '[卵|たまご]と[砂糖|さとう]を[混ぜ合|まぜあ]わせる。', zh: '把蛋和砂糖混合攪拌。' },
