  'n3-1269': { ja: 'この[学校|がっこう]は[新|あたら]しい[教|おし]え[方|かた]を[取り入|とりい]れている。', zh: '這所學校引進了新的教學方式。' },
  'n3-1270': { ja: '[試合|しあい]が[中止|ちゅうし]になり、チケット[代|だい]が[払い戻|はらいもど]された。', zh: '比賽取消，票款已經退還了。' },
