  'n3-1276': { ja: '[昨日|きのう]のパーティーはとても[盛り上|もりあ]がった。', zh: '昨天的派對氣氛非常熱烈。' },
  'n3-1277': { ja: '[見慣|みな]れない[車|くるま]が[家|いえ]の[前|まえ]に[止|と]まっている。', zh: '家門前停著一輛沒見過的車。' },
  'n3-1278': { ja: '[声|こえ]が[小|ちい]さくて、よく[聞き取|ききと]れなかった。', zh: '聲音太小，沒能聽清楚。' },
  'n3-1279': { ja: '[先生|せんせい]が[合格|ごうかく][者|しゃ]の[名前|なまえ]を[読み上|よみあ]げた。', zh: '老師唸出了合格者的名字。' },
  'n3-1280': { ja: '[彼|かれ]の[言葉|ことば]を[一|いち][字|じ][一|いち][句|く][書き取|かきと]った。', zh: '我把他的話一字一句記了下來。' },
  'n3-1281': { ja: '[母|はは]に[叱|しか]られて、つい[言い返|いいかえ]してしまった。', zh: '被媽媽罵，忍不住頂了嘴。' },
  'n3-1282': { ja: '[難|むずか]しい[言葉|ことば]を[簡単|かんたん]な[言葉|ことば]に[言い換|いいか]えてください。', zh: '請把難懂的詞換成簡單的說法。' },
  'n3-1283': { ja: '[彼|かれ]は[黙|だま]って[一|いち][枚|まい]の[写真|しゃしん]を[差し出|さしだ]した。', zh: '他默默地遞出一張照片。' },
  'n3-1284': { ja: '[名前|なまえ]を[呼|よ]ばれて[振り向|ふりむ]くと、[誰|だれ]もいなかった。', zh: '聽見有人叫我名字，回頭卻一個人也沒有。' },
  'n3-1285': { ja: '[帰|かえ]ったらすぐに[部屋|へや][着|ちゃく]に[着替|きが]える。', zh: '一回家就馬上換上居家服。' },
  'n3-1286': { ja: '[厳|きび]しい[競争|きょうそう]の[中|なか]で[生き残|いきのこ]るのは[大変|たいへん]だ。', zh: '要在激烈的競爭中存活下來很不容易。' },
  'n3-1287': { ja: 'その[会社|かいしゃ]は[来月|らいげつ][新|あたら]しいゲームを[売り出|うりだ]す。', zh: '那家公司下個月要推出新遊戲。' },
  'n3-1288': { ja: '[古|ふる]くなったので、パソコンを[買い換|かいか]えた。', zh: '電腦舊了，所以換了一台新的。' },
