  'n3-1292': { ja: '[合格|ごうかく]の[知|し]らせに、[彼|かれ]は[飛び上|とびあ]がって[喜|よろこ]んだ。', zh: '收到合格通知，他高興得跳了起來。' },
  'n3-1293': { ja: '[町|まち][全体|ぜんたい]でごみの[問題|もんだい]に[取り組|とりく]んでいる。', zh: '整個城鎮都在致力於解決垃圾問題。' },
  'n3-1294': { ja: '[休|やす]みを[取|と]って、ようやく[元気|げんき]を[取り戻|とりもど]した。', zh: '休息了一陣子，總算恢復了精神。' },
  'n3-1295': { ja: '[残|のこ]った[料理|りょうり]を[家|いえ]に[持ち帰|もちかえ]ってもいいですか。', zh: '剩下的菜可以帶回家嗎？' },
  'n3-1296': { ja: '[彼|かれ]はいつもカメラを[持ち歩|もちある]いている。', zh: '他總是隨身帶著相機。' },
