  'n3-1298': { ja: '[祖父母|そふぼ]は[田舎|いなか]で[静|しず]かに[暮|く]らしている。', zh: '祖父母在鄉下安靜地過日子。' },
  'n3-1299': { ja: '[危|あぶ]ないから、[子|こ]どもの[手|て]を[離|はな]さないでね。', zh: '很危險，別放開小孩的手喔。' },
