  'n3-1301': { ja: '[机|つくえ]を[窓|まど]の[近|ちか]くに[移|うつ]した。', zh: '把桌子搬到了靠窗的地方。' },
  'n3-1302': { ja: '[毎日|まいにち][同|おな]じ[料理|りょうり]だと[飽|あ]きてしまう。', zh: '每天吃一樣的菜會膩。' },
  'n3-1303': { ja: 'みんなで[先生|せんせい]の[誕生|たんじょう][日|び]を[祝|いわ]った。', zh: '大家一起為老師慶生。' },
