  'n3-1309': { ja: '[夜道|よみち]で[女性|じょせい]が[何者|なにもの]かに[襲|おそ]われた。', zh: '一名女性在夜路上遭到不明人士襲擊。' },
  'n3-1310': { ja: '[後|うし]ろから[急|きゅう]に[声|こえ]をかけて、[友達|ともだち]を[驚|おどろ]かした。', zh: '從背後突然出聲，嚇了朋友一跳。' },
  'n3-1311': { ja: '[川|かわ]で[溺|おぼ]れている[子|こ]どもを[助|たす]けた。', zh: '救起了在河裡溺水的孩子。' },
  'n3-1312': { ja: '[階段|かいだん]を[下|お]りるときは[足元|あしもと]に[気|き]をつけて。', zh: '下樓梯時要注意腳步。' },
  'n3-1313': { ja: '[参加|さんか][者|しゃ]は[二|に][十人|じゅうにん]に[限|かぎ]ります。', zh: '參加人數限定二十人。' },
  'n3-1314': { ja: 'ゼリーが[冷蔵庫|れいぞうこ]で[固|かた]まった。', zh: '果凍在冰箱裡凝固了。' },
  'n3-1315': { ja: '[多|おお]くの[人|ひと]が[彼|かれ]の[死|し]を[悲|かな]しんだ。', zh: '很多人為他的死感到悲傷。' },
  'n3-1316': { ja: '[今回|こんかい]は[新|あたら]しい[刑事|けいじ]とコンビを[組|く]むことになった。', zh: '這次要和新來的刑警搭檔。' },
  'n3-1317': { ja: '[急|いそ]いで[飲|の]むと、コーヒーをこぼすよ。', zh: '喝太急的話會把咖啡灑出來喔。' },
  'n3-1318': { ja: '[水|みず]を[入|い]れすぎると、コップからこぼれる。', zh: '水倒太多的話，會從杯子溢出來。' },
  'n3-1319': { ja: '[父|ちち]は[毎朝|まいあさ]ネクタイを[締|し]めて[出|で]かける。', zh: '爸爸每天早上打好領帶出門。' },
  'n3-1320': { ja: '[計画|けいかく]を[予定|よてい]どおりに[進|すす]めている。', zh: '計畫正按照預定進行中。' },
