  'n3-1322': { ja: '[姉|あね]は[髪|かみ]を[茶色|ちゃいろ]に[染|そ]めた。', zh: '姊姊把頭髮染成了褐色。' },
  'n3-1323': { ja: '[母親|ははおや]は[赤|あか]ちゃんを[優|やさ]しく[抱|だ]いていた。', zh: '媽媽溫柔地抱著嬰兒。' },
