  'n3-1340': { ja: '[角|かく]を[曲|ま]がったところで[人|ひと]とぶつかった。', zh: '在轉角處和人撞個正著。' },
  'n3-1341': { ja: '[会議|かいぎ]の[内容|ないよう]を[一|いち][枚|まい]の[紙|かみ]に[纏|まと]めた。', zh: '把會議內容彙整成一張紙。' },
  'n3-1342': { ja: 'この[経験|けいけん]から[多|おお]くのことを[学|まな]んだ。', zh: '從這次經驗中學到了很多。' },
