  'n3-1345': { ja: 'この[仕事|しごと]は[私|わたし]に[向|む]いていると[思|おも]う。', zh: '我覺得這份工作很適合我。' },
  'n3-1346': { ja: '[社長|しゃちょう]は[部下|ぶか]に[調査|ちょうさ]を[命|めい]じた。', zh: '社長命令部下進行調查。' },
  'n3-1347': { ja: '[赤|あか]い[服|ふく]はとても[目立|めだ]つ。', zh: '紅色的衣服非常顯眼。' },
