  'n3-1351': { ja: '[彼女|かのじょ]は[会議|かいぎ]の[司会|しかい]を[務|つと]めた。', zh: '她擔任了會議的主持人。' },
  'n3-1352': { ja: '[彼|かれ]はドラマで[刑事|けいじ]の[役|やく]を[演|えん]じている。', zh: '他在連續劇裡飾演刑警。' },
