  'n3-1363': { ja: '[彼女|かのじょ]は[私|わたし]の[耳元|みみもと]で[何|なに]か[囁|ささや]いた。', zh: '她在我耳邊低聲說了些什麼。' },
  'n3-1364': { ja: '[駅|えき]で[昔|むかし]の[友達|ともだち]にばったり[会|あ]った。', zh: '在車站突然碰見了以前的朋友。' },
  'n3-1365': { ja: '[彼女|かのじょ]は[美|うつく]しい[音楽|おんがく]にうっとりと[聞き入|ききい]った。', zh: '她陶醉地聆聽著優美的音樂。' },
