  'n3-1394': { ja: '[風|かぜ]で[窓|まど]ががたがた[鳴|な]っている。', zh: '窗戶被風吹得嘎嗒作響。' },
  'n3-1395': { ja: '[寒|さむ]くて[体|からだ]がぶるぶる[震|ふる]えた。', zh: '冷得全身發抖。' },
