  'n3-1407': { ja: '[町|まち]で[相次|あいつ]いで[火事|かじ]が[起|お]きた。', zh: '鎮上接二連三發生火災。' },
  'n3-1408': { ja: '[彼|かれ]は[質問|しつもん]に[即座|そくざ]に[答|こた]えた。', zh: '他當場回答了問題。' },
  'n3-1409': { ja: '[通報|つうほう]を[受|う]けて、[警察|けいさつ]はすぐさま[出動|しゅつどう]した。', zh: '接到報案，警察立刻出動。' },
