  'n3-1608': { ja: '[雨|あめ]に[降|ふ]られて[財布|さいふ]もなくして、[最悪|さいあく]の[一|いち][日|にち]だった。', zh: '淋了雨又掉了錢包，真是最糟的一天。' },
  'n3-1609': { ja: 'この[部屋|へや]は[勉強|べんきょう]に[最適|さいてき]だ。', zh: '這個房間最適合讀書。' },
  'n3-1610': { ja: '[今日|きょう]は[絶好|ぜっこう]の[釣|つ]り[日和|ひより]だ。', zh: '今天是絕佳的釣魚天氣。' },
  'n3-1611': { ja: '[会議|かいぎ]が[延期|えんき]になったのは[好都合|こうつごう]だった。', zh: '會議延期反而正好方便。' },
  'n3-1612': { ja: '[何|なに]か[不都合|ふつごう]なことがあれば[教|おし]えてください。', zh: '如果有什麼不方便的地方請告訴我。' },
  'n3-1613': { ja: '[彼|かれ]は[私|わたし]の[提案|ていあん]に[否定的|ひていてき]だった。', zh: '他對我的提議持否定態度。' },
  'n3-1614': { ja: 'みんな[肯定的|こうていてき]な[意見|いけん]を[出|だ]してくれた。', zh: '大家都提出了正面的意見。' },
  'n3-1615': { ja: '[新聞|しんぶん]は[政府|せいふ]に[批判的|ひはんてき]だ。', zh: '報紙對政府持批判態度。' },
