  'n3-1618': { ja: '[彼女|かのじょ]は[進歩的|しんぽてき]な[考|かんが]えを[持|も]っている。', zh: '她有開明進步的想法。' },
  'n3-1619': { ja: 'この[旅館|りょかん]は[古風|こふう]な[造|つく]りだ。', zh: '這間旅館的建築很古樸。' },
  'n3-1620': { ja: 'この[旧式|きゅうしき]のカメラはまだ[使|つか]える。', zh: '這台舊式相機還能用。' },
  'n3-1621': { ja: '[誕生|たんじょう][日|び]に[高級|こうきゅう]なレストランへ[行|い]った。', zh: '生日時去了高級餐廳。' },
  'n3-1622': { ja: 'これは[上等|じょうとう]な[牛肉|ぎゅうにく]だ。', zh: '這是上等的牛肉。' },
