  'n3-1628': { ja: '[彼|かれ]は[律儀|りちぎ]に[毎年|まいとし][年賀状|ねんがじょう]をくれる。', zh: '他很講情義，每年都寄賀年卡給我。' },
  'n3-1629': { ja: '[彼|かれ]は[交渉|こうしょう]で[強気|つよき]な[態度|たいど]を[見|み]せた。', zh: '他在交涉中態度強硬。' },
  'n3-1630': { ja: '[試合|しあい]の[前|まえ]に[弱気|よわき]になってはいけない。', zh: '比賽前不可以變得沒自信。' },
