  'n3-1632': { ja: '[姉|あね]は[社交的|しゃこうてき]で[友達|ともだち]が[多|おお]い。', zh: '姊姊擅長社交，朋友很多。' },
  'n3-1633': { ja: '[彼|かれ]は[内向的|ないこうてき]で、あまり[話|はな]さない。', zh: '他很內向，不太說話。' },
