  'n3-1640': { ja: '[二人|ふたり]はドラマチックな[再会|さいかい]を[果|は]たした。', zh: '兩人戲劇般地重逢了。' },
  'n3-1641': { ja: '[彼女|かのじょ]にはどこかミステリアスな[魅力|みりょく]がある。', zh: '她身上有種神祕的魅力。' },
  'n3-1642': { ja: '[祖母|そぼ]は[八|はち][十歳|じゅっさい]でもとてもアクティブだ。', zh: '祖母八十歲了還很活躍。' },
  'n3-1643': { ja: 'プライベートな[質問|しつもん]には[答|こた]えられません。', zh: '私人問題恕不回答。' },
