  'n3-1645': { ja: 'モダンなデザインの[家|いえ]に[住|す]みたい。', zh: '想住在設計摩登的房子。' },
  'n3-1646': { ja: 'このバンドはオリジナルの[曲|きょく]を[演奏|えんそう]する。', zh: '這個樂團演奏原創曲目。' },
  'n3-1647': { ja: '[彼|かれ]は[新|あたら]しい[音楽|おんがく]を[創|つく]ることに[情熱|じょうねつ]を[燃|も]やしている。', zh: '他熱衷於創作新的音樂。' },
  'n3-1648': { ja: '[人生|じんせい]を[旅|たび]に[例|たと]える[人|ひと]は[多|おお]い。', zh: '很多人把人生比喻為旅行。' },
  'n3-1649': { ja: '[祖父|そふ]は[木|き]で[仏像|ぶつぞう]を[彫|ほ]っている。', zh: '祖父用木頭雕佛像。' },
