  'n3-1651': { ja: '[十|じゅう][年|ねん][後|ご]の[自分|じぶん]を[思い描|おもいえが]いてみよう。', zh: '試著想像十年後的自己吧。' },
  'n3-1652': { ja: '[彼|かれ]は[絵|え]を[描|えが]くことに[生|い]きがいを[見出|みいだ]した。', zh: '他在畫畫中找到了人生意義。' },
  'n3-1653': { ja: '[今|いま]、[若者|わかもの]の[間|あいだ]でこの[歌|うた]が[流行|はや]っている。', zh: '現在年輕人之間流行這首歌。' },
