  'n3-2234': { ja: '[病院|びょういん]に[健康保険|けんこうほけん][証|あかし]を[持|も]っていった。', zh: '帶了健保卡去醫院。' },
  'n3-2235': { ja: '[会社|かいしゃ]を[辞|や]めて[雇用保険|こようほけん]の[手続|てつづ]きをした。', zh: '辭職後辦了就業保險手續。' },
